                            if before['quantity']>before['low_threshold'] and before['quantity']-qty<=before['low_threshold']:
                                watchers=db.execute("SELECT id FROM users WHERE active=1 AND (role='ADMIN' OR outlet_id=? AND role IN ('STAFF','DH_MANAGER'))",(data['outlet_id'],)).fetchall()
