    def reports():
        db=get_db(); scope=outlet_scope(g.user); start=request.args.get('from',date.today().isoformat()); end=request.args.get('to',date.today().isoformat()); clauses=['date(created_at)>=?','date(created_at)<=?']; args=[start,end]
        if scope is not None: clauses.append('outlet_id=?'); args.append(scope)
