        by_outlet=db.execute('SELECT x.name,count(o.id) orders,coalesce(sum(CASE WHEN o.status="COMPLETED" THEN o.total_cents ELSE 0 END),0) revenue FROM outlets x LEFT JOIN orders o ON o.outlet_id=x.id AND date(o.created_at)>=? AND date(o.created_at)<=?'+(' WHERE x.id=?' if scope is not None else '')+' GROUP BY x.id ORDER BY x.name',([start,end]+([scope] if scope is not None else []))).fetchall()
