def login_required(fn):
    @wraps(fn)
    def wrapped(*a,**kw):
        if not g.user: return redirect(url_for('login',next=request.path))
        return fn(*a,**kw)
    return wrapped
def roles(*allowed):
    def dec(fn):
        @wraps(fn)
        def wrapped(*a,**kw):
            if not g.user: return redirect(url_for('login'))
            if g.user['role'] not in allowed: abort(403)
            return fn(*a,**kw)
        return wrapped
    return dec
