def test_cart_checkout_payment_lifecycle_and_otp(app,client):
    login(client)
    t=csrf(client); assert client.post('/cart/add/1',data={'csrf_token':t,'quantity':'2'}).status_code==302
    t=csrf(client); res=client.post('/cart/add/2',data={'csrf_token':t,'quantity':'1'},follow_redirects=True); assert b'another outlet' in res.data
    t=csrf(client); res=client.post('/checkout',data={'csrf_token':t,'payment_method':'MOCK_ONLINE','payment_result':'failed'},follow_redirects=True); assert b'payment failed' in res.data.lower()
    t=csrf(client); res=client.post('/checkout',data={'csrf_token':t,'payment_method':'PAY_AT_PICKUP'},follow_redirects=True); assert b'CF-' in res.data
    with app.app_context():
        from app import get_db
        db=get_db(); oid=db.execute('SELECT id FROM orders').fetchone()['id']; assert db.execute('SELECT total_cents FROM orders WHERE id=?',(oid,)).fetchone()['total_cents']==24000; assert db.execute('SELECT quantity FROM inventory_items WHERE item_name="Rice Bowl"').fetchone()['quantity']==8
    login(client,'staff@krea.edu.in'); t=csrf(client); client.post(f'/orders/{oid}/status',data={'csrf_token':t,'status':'ACCEPTED'}); t=csrf(client); client.post(f'/orders/{oid}/status',data={'csrf_token':t,'status':'PREPARING'}); t=csrf(client); client.post(f'/orders/{oid}/status',data={'csrf_token':t,'status':'READY'})
    login(client); page=client.get(f'/orders/{oid}').data.decode(); import re; otp=re.search(r'>(\d{6})</strong>',page).group(1)
    login(client,'staff@krea.edu.in'); t=csrf(client); bad=client.post(f'/orders/{oid}/verify-otp',data={'csrf_token':t,'otp':'999999'},follow_redirects=True); assert b'OTP is invalid' in bad.data
    t=csrf(client); assert client.post(f'/orders/{oid}/verify-otp',data={'csrf_token':t,'otp':otp},follow_redirects=True).status_code==200
    t=csrf(client); assert b'already used' in client.post(f'/orders/{oid}/verify-otp',data={'csrf_token':t,'otp':otp},follow_redirects=True).data
    with app.app_context():
        from app import get_db
        assert get_db().execute('SELECT status FROM orders WHERE id=?',(oid,)).fetchone()['status']=='COMPLETED'

def test_student_cannot_read_another_order(client):
    login(client); t=csrf(client); client.post('/cart/add/1',data={'csrf_token':t,'quantity':1}); t=csrf(client); client.post('/checkout',data={'csrf_token':t,'payment_method':'PAY_AT_PICKUP'})
    with client.session_transaction() as s: pass
    login(client,'otherstudent@krea.edu.in')
    assert client.get('/orders/1').status_code==403

def test_invalid_transition_and_student_cancellation_restores_stock(app,client):
    login(client); t=csrf(client); client.post('/cart/add/1',data={'csrf_token':t,'quantity':1}); t=csrf(client); client.post('/checkout',data={'csrf_token':t,'payment_method':'PAY_AT_PICKUP'})
    login(client,'staff@krea.edu.in'); t=csrf(client); client.post('/orders/1/status',data={'csrf_token':t,'status':'READY'})
    with app.app_context():
        from app import get_db
        assert get_db().execute('SELECT status FROM orders WHERE id=1').fetchone()['status']=='PENDING'
    login(client); t=csrf(client); response=client.post('/orders/1/status',data={'csrf_token':t,'status':'CANCELLED'},follow_redirects=True)
    assert b'Order updated' in response.data
    with app.app_context():
        from app import get_db
        db=get_db(); assert db.execute('SELECT status FROM orders WHERE id=1').fetchone()['status']=='CANCELLED'; assert db.execute("SELECT quantity FROM inventory_items WHERE item_name='Rice Bowl'").fetchone()['quantity']==10

def test_manager_is_restricted_to_dining_hall(client):
    login(client,'manager@krea.edu.in')
    assert client.get('/outlet/3').status_code==200
    assert client.get('/outlet/1').status_code==403
    assert client.get('/admin/users').status_code==403

def test_admin_and_report_access(client):
    login(client,'admin@krea.edu.in')
    assert client.get('/admin/users').status_code==200
    assert client.get('/admin/outlets').status_code==200
    assert client.get('/admin/audit').status_code==200
    assert client.get('/reports').status_code==200
